-- A frame records declarations, never an authorization receipt.
CREATE TABLE native_turn_frames (
 workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
 id uuid PRIMARY KEY, session_id uuid NOT NULL,
 format integer NOT NULL CHECK(format=1), manifest_digest text NOT NULL CHECK(manifest_digest ~ '^[a-f0-9]{64}$'),
 FOREIGN KEY(workspace_id,id) REFERENCES session_context_scope_revisions(workspace_id,id) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE native_turn_publication_work (
 transaction_id bigint NOT NULL,workspace_id uuid NOT NULL,frame_id uuid NOT NULL,
 session_id uuid NOT NULL,context jsonb NOT NULL,original_sources jsonb NOT NULL,
 prepared jsonb NOT NULL, completion_ready boolean NOT NULL DEFAULT false, PRIMARY KEY(transaction_id,frame_id)
);
CREATE TABLE native_turn_publication_events (
 transaction_id bigint NOT NULL,frame_id uuid NOT NULL,event jsonb NOT NULL,fired boolean NOT NULL DEFAULT false,
 PRIMARY KEY(transaction_id,frame_id,event)
);
CREATE TABLE native_turn_publication_seals (
 transaction_id bigint NOT NULL,frame_id uuid NOT NULL,outputs jsonb NOT NULL,
 PRIMARY KEY(transaction_id,frame_id)
);
CREATE TABLE native_turn_publication_impossible (id uuid PRIMARY KEY CHECK(false));
CREATE TABLE native_turn_publication_debt (
 transaction_id bigint NOT NULL,frame_id uuid NOT NULL,
 PRIMARY KEY(transaction_id,frame_id),
 CONSTRAINT application_field_derivation_dependencies FOREIGN KEY(frame_id)
 REFERENCES native_turn_publication_impossible(id) DEFERRABLE INITIALLY DEFERRED
);
DO $private_tables$ DECLARE t regclass;BEGIN
 FOREACH t IN ARRAY ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,
  'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,
  'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass] LOOP
 EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('REVOKE ALL ON %s FROM PUBLIC,app_user',t);
 IF EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=t AND(c.relpersistence<>'p' OR c.relkind<>'r' OR EXISTS(SELECT 1 FROM pg_rewrite WHERE ev_class=c.oid) OR c.relowner<>(SELECT relowner FROM pg_class WHERE oid='memories'::regclass)
  OR EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee<>c.relowner OR a.grantor<>c.relowner OR a.is_grantable)
  OR EXISTS(SELECT 1 FROM pg_attribute column_acl CROSS JOIN LATERAL aclexplode(column_acl.attacl) a WHERE column_acl.attrelid=c.oid
   AND(a.grantee<>c.relowner OR a.grantor<>c.relowner OR a.is_grantable))))
 THEN RAISE EXCEPTION 'native_turn_publication_private_table_acl: %',t;END IF;
 END LOOP;
END $private_tables$;
DO $$ DECLARE expression text;BEGIN
 SELECT pg_get_expr(conbin,conrelid) INTO STRICT expression FROM pg_constraint
 WHERE conrelid='session_context_scope_revisions'::regclass AND conname='session_context_scope_revisions_parent_kind_check';
 ALTER TABLE session_context_scope_revisions DROP CONSTRAINT session_context_scope_revisions_parent_kind_check;
 EXECUTE 'ALTER TABLE session_context_scope_revisions ADD CONSTRAINT session_context_scope_revisions_parent_kind_check CHECK(('||expression||') OR parent_kind=''turn_frame'')';
END $$;
CREATE FUNCTION native_turn_frame_payload_shape(p jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE sources jsonb;n jsonb;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR p-ARRAY['kind','originalSources','declaredSources']<>'{}'
  OR p->>'kind' IS DISTINCT FROM 'native_turn_frame_v1' THEN RETURN false;END IF;
 FOREACH sources IN ARRAY ARRAY[p->'originalSources',p->'declaredSources'] LOOP
  IF jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 4096
   OR (SELECT count(DISTINCT (v->>'resourceKind',v->>'resourceId')) FROM jsonb_array_elements(sources) v)<>jsonb_array_length(sources)
  THEN RETURN false;END IF;
  FOR n IN SELECT value FROM jsonb_array_elements(sources) LOOP
   IF n-ARRAY['workspaceId','userId','assistantId','sensitivity','compartments','projectIds','resourceKind','resourceId','version']<>'{}'
    OR entity_derivation_envelope_valid(n) IS NOT TRUE OR NOT n ?& ARRAY['resourceKind','resourceId','version']
    OR jsonb_typeof(n->'resourceKind') IS DISTINCT FROM 'string' OR jsonb_typeof(n->'resourceId') IS DISTINCT FROM 'string' OR n->>'resourceKind' NOT IN('session_message','session_context_revision','application_field','workspace_file')
    OR jsonb_typeof(n->'version') IS DISTINCT FROM 'string' OR length(btrim(n->>'version')) NOT BETWEEN 1 AND 256
    OR (n->>'resourceId')::uuid IS NULL THEN RETURN false;END IF;
  END LOOP;
 END LOOP;
 RETURN (p->'declaredSources') @> (p->'originalSources');
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN RETURN false;
END $$;
CREATE FUNCTION native_turn_frame_pair(w uuid,i uuid) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE f native_turn_frames;r session_context_scope_revisions;d scope_derivations;parent sessions;p jsonb;edges jsonb;declared jsonb;
BEGIN
 SELECT * INTO f FROM native_turn_frames WHERE workspace_id=w AND id=i;
 SELECT * INTO r FROM session_context_scope_revisions WHERE workspace_id=w AND id=i;
 SELECT id,visibility,user_id INTO parent.id,parent.visibility,parent.user_id FROM sessions WHERE workspace_id=w AND id=r.session_id;
 SELECT content INTO p FROM session_context_revision_contents WHERE workspace_id=w AND revision_id=i;
 IF f.id IS NULL OR r.id IS NULL OR parent.id IS NULL OR r.scope_held OR scope_review_state_held('session_context_revision',i)
  OR r.user_id IS DISTINCT FROM (CASE WHEN parent.visibility='personal' THEN parent.user_id ELSE NULL END)
  OR r.assistant_id IS NOT NULL OR f.format<>1 OR r.parent_kind IS DISTINCT FROM 'turn_frame'
  OR r.parent_id IS DISTINCT FROM i OR r.session_id IS DISTINCT FROM f.session_id OR r.scope_version<>1
  OR native_turn_frame_payload_shape(p) IS NOT TRUE OR r.payload_sha256<>encode(sha256(convert_to(p::text,'UTF8')),'hex')
  OR f.manifest_digest<>r.payload_sha256 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'declaredSources') n
   WHERE n->>'workspaceId' IS DISTINCT FROM w::text OR n->>'resourceKind'='session_context_revision' AND n->>'resourceId'=i::text)
 THEN RETURN false;END IF;
 SELECT * INTO d FROM scope_derivations WHERE workspace_id=w AND resource_kind='session_context_revision' AND resource_id=i AND resource_version='1';
 IF d.id IS NULL OR (d.user_id,d.assistant_id,d.sensitivity,d.compartments,d.project_ids)
  IS DISTINCT FROM (r.user_id,r.assistant_id,r.sensitivity,r.compartments,r.project_ids) THEN RETURN false;END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_array(source_kind,source_id,source_version) ORDER BY source_kind,source_id,source_version),'[]') INTO edges
 FROM scope_derivation_sources WHERE workspace_id=w AND derivation_id=d.id;
 SELECT jsonb_agg(jsonb_build_array(n->>'resourceKind',(n->>'resourceId')::uuid,n->>'version') ORDER BY n->>'resourceKind',(n->>'resourceId')::uuid,n->>'version')
 INTO declared FROM jsonb_array_elements(p->'declaredSources') n;
 IF edges IS DISTINCT FROM declared OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'declaredSources') n
  WHERE n->>'userId' IS NOT NULL AND n->>'userId' IS DISTINCT FROM r.user_id::text
   OR sensitivity_rank(n->>'sensitivity')>sensitivity_rank(r.sensitivity)
   OR NOT to_jsonb(r.compartments) @> (n->'compartments') OR NOT to_jsonb(r.project_ids) @> (n->'projectIds')) THEN RETURN false;END IF;
 RETURN true;
END $$;
CREATE FUNCTION native_turn_frame_immutable() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' AND NOT EXISTS(SELECT 1 FROM workspaces WHERE id=OLD.workspace_id) THEN RETURN OLD;END IF;
 RAISE EXCEPTION 'scope_evidence_immutable' USING ERRCODE='22023';
END $$;
CREATE TRIGGER native_turn_frame_immutable BEFORE UPDATE OR DELETE ON native_turn_frames FOR EACH ROW EXECUTE FUNCTION native_turn_frame_immutable();

CREATE FUNCTION native_turn_validate_frame_pair() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF native_turn_helpers_current() IS NOT TRUE OR native_turn_frame_pair(NEW.workspace_id,NEW.id) IS NOT TRUE THEN
  IF EXISTS(SELECT 1 FROM native_turn_publication_work op WHERE op.transaction_id=txid_current() AND op.frame_id=NEW.id AND op.workspace_id=NEW.workspace_id)
  THEN RAISE EXCEPTION 'native_turn_construction_unavailable' USING ERRCODE='PNT02';END IF;
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';
 END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER native_turn_frame_pair AFTER INSERT ON native_turn_frames DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION native_turn_validate_frame_pair();

-- Cleanup is an authenticated effect boundary, including late deferred-trigger interleavings.
CREATE FUNCTION native_turn_guard_completion_debt() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE work native_turn_publication_work;
BEGIN
 SELECT * INTO work FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=OLD.frame_id;
 IF OLD.transaction_id<>txid_current() OR work.frame_id IS NULL OR work.completion_ready IS DISTINCT FROM true
  OR work.context IS DISTINCT FROM native_turn_context()
  OR (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid='native_turn_publication_contract()'::regprocedure) IS DISTINCT FROM '__PUBLICATION_CONTRACT_PIN__'
  OR native_turn_publication_contract() IS NOT TRUE OR native_turn_helpers_current() IS NOT TRUE
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 RETURN OLD;
END $$;
CREATE TRIGGER native_turn_completion_debt_guard BEFORE DELETE ON native_turn_publication_debt
FOR EACH ROW EXECUTE FUNCTION native_turn_guard_completion_debt();

CREATE FUNCTION native_turn_prepare_publication(w uuid,s uuid,producer text,sources jsonb,target jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE parent jsonb;proof jsonb;roots jsonb;declared jsonb;source jsonb;current_source jsonb;
 actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;tier text;teams text[];projects uuid[];
BEGIN
 IF native_turn_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;
 parent:=lock_native_session_context_publication(w,s);
 IF jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 4096
  OR length(btrim(producer)) NOT BETWEEN 1 AND 256 OR entity_derivation_envelope_valid(target) IS NOT TRUE
  OR target->>'workspaceId' IS DISTINCT FROM w::text OR target->>'assistantId' IS NOT NULL
  OR target->>'userId' IS NOT NULL AND target->>'userId' IS DISTINCT FROM actor::text
  OR parent->>'userId' IS NOT NULL AND parent->>'userId' IS DISTINCT FROM target->>'userId' THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 -- Initial native profile retains exact current versions. Other D1 cases use the original writer.
 IF target->'userId' IS DISTINCT FROM parent->'userId' OR EXISTS(SELECT 1 FROM jsonb_array_elements(sources) n
  WHERE n->>'resourceKind' NOT IN('session_message','session_context_revision','application_field','workspace_file')) THEN RETURN NULL;END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(sources) LOOP
  IF entity_derivation_envelope_valid(source) IS NOT TRUE OR source->>'workspaceId' IS DISTINCT FROM w::text
   OR jsonb_typeof(source->'version') IS DISTINCT FROM 'string' OR length(btrim(source->>'version')) NOT BETWEEN 1 AND 256
   OR (source->>'resourceId')::uuid IS NULL THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('kind',n->'resourceKind','id',n->'resourceId','version',n->'version')) INTO roots FROM jsonb_array_elements(sources) n;
 proof:=read_native_turn_requirements(w,roots);
 IF proof->>'available' IS DISTINCT FROM 'true' THEN RETURN NULL;END IF;
 SELECT jsonb_agg(n ORDER BY n::text) INTO declared FROM(SELECT DISTINCT value n FROM jsonb_array_elements(sources||(proof->'immutable'))) all_sources;
 IF jsonb_array_length(declared)>4096 OR (SELECT count(DISTINCT(n->>'resourceKind',n->>'resourceId')) FROM jsonb_array_elements(declared) n)<>jsonb_array_length(declared)
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 tier:=CASE WHEN sensitivity_rank(target->>'sensitivity')>sensitivity_rank(parent->>'sensitivity') THEN target->>'sensitivity' ELSE parent->>'sensitivity' END;
 teams:=ARRAY(SELECT DISTINCT value FROM jsonb_array_elements_text((parent->'compartments')||(target->'compartments')) value ORDER BY value);
 projects:=ARRAY(SELECT DISTINCT value::uuid FROM jsonb_array_elements_text((parent->'projectIds')||(target->'projectIds')) value ORDER BY value::uuid);
 FOR source IN SELECT value FROM jsonb_array_elements(declared) LOOP
  SELECT n INTO current_source FROM jsonb_array_elements(proof->'current') n
  WHERE n->>'resourceKind'=source->>'resourceKind' AND n->>'resourceId'=source->>'resourceId';
  IF current_source IS NULL OR current_source IS DISTINCT FROM source THEN RETURN NULL;END IF;
  IF source->>'userId' IS NOT NULL AND source->'userId' IS DISTINCT FROM target->'userId' THEN RETURN NULL;END IF;
  IF source->>'userId' IS NOT NULL AND source->>'userId' IS DISTINCT FROM actor::text THEN
   RAISE EXCEPTION 'scope_visibility_incompatible' USING ERRCODE='22023';END IF;
  IF sensitivity_rank(source->>'sensitivity')>sensitivity_rank(tier) THEN tier:=source->>'sensitivity';END IF;
  teams:=ARRAY(SELECT DISTINCT value FROM unnest(teams||ARRAY(SELECT jsonb_array_elements_text(source->'compartments'))) value ORDER BY value);
  projects:=ARRAY(SELECT DISTINCT value FROM unnest(projects||ARRAY(SELECT jsonb_array_elements_text(source->'projectIds')::uuid)) value ORDER BY value);
 END LOOP;
 IF member_operation_scope_allows(w,tier,teams,true) IS NOT TRUE OR agent_mutation_scope_allows(teams) IS NOT TRUE
  OR agent_read_scope_allows(tier,teams,projects) IS NOT TRUE THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('scope',jsonb_build_object('workspaceId',w,'userId',target->'userId','assistantId',NULL,
  'sensitivity',tier,'compartments',teams,'projectIds',projects),'retained',declared,
  'proof',jsonb_build_object('validUntil',proof->'validUntil','admitted',true,'immutable',proof->'immutable','current',proof->'current'));
END $$;

-- The lookup identifies only a writer-owned current operation. It grants no source admission.
CREATE FUNCTION native_turn_event_frame(w uuid,d uuid) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT op.frame_id FROM native_turn_publication_work op JOIN scope_derivations output ON output.workspace_id=w AND output.id=d
 WHERE op.transaction_id=txid_current() AND op.workspace_id=w AND
 ((output.resource_kind='session_context_revision' AND output.resource_id=op.frame_id AND output.resource_version='1')
 OR output.resource_kind='session_message' AND EXISTS(SELECT 1 FROM scope_derivation_sources e
  WHERE e.workspace_id=w AND e.derivation_id=d AND e.source_kind='session_context_revision' AND e.source_id=op.frame_id AND e.source_version='1'))
$$;
CREATE FUNCTION native_turn_capture_event(event jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE selected_frame uuid;w uuid:=(event->>'workspace_id')::uuid;
BEGIN
 selected_frame:=native_turn_event_frame(w,(event->>'derivation_id')::uuid);
 IF selected_frame IS NULL THEN RETURN false;END IF;
 IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid='native_turn_publication_contract()'::regprocedure) IS DISTINCT FROM '__PUBLICATION_CONTRACT_PIN__'
  OR native_turn_publication_contract() IS NOT TRUE OR EXISTS(SELECT 1 FROM native_turn_publication_seals seal WHERE seal.transaction_id=txid_current() AND seal.frame_id=selected_frame) THEN
  RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 INSERT INTO native_turn_publication_events(transaction_id,frame_id,event) VALUES(txid_current(),selected_frame,event);
 RETURN true;
END $$;
CREATE FUNCTION native_turn_validate_event(event jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE selected_frame uuid;work native_turn_publication_work;seal native_turn_publication_seals;output scope_derivations;r session_context_scope_revisions;
BEGIN
 selected_frame:=native_turn_event_frame((event->>'workspace_id')::uuid,(event->>'derivation_id')::uuid);
 IF selected_frame IS NULL THEN RETURN false;END IF;
 SELECT * INTO work FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=selected_frame;
 SELECT * INTO seal FROM native_turn_publication_seals WHERE transaction_id=txid_current() AND frame_id=selected_frame;
 IF seal.frame_id IS NULL THEN RAISE EXCEPTION 'native_turn_construction_unavailable' USING ERRCODE='PNT02';END IF;
 IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p WHERE p.oid='native_turn_publication_contract()'::regprocedure) IS DISTINCT FROM '__PUBLICATION_CONTRACT_PIN__'
  OR native_turn_publication_contract() IS NOT TRUE OR work.context IS DISTINCT FROM native_turn_context()
  OR NOT EXISTS(SELECT 1 FROM native_turn_publication_debt WHERE transaction_id=txid_current() AND frame_id=selected_frame) THEN
  RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 SELECT * INTO output FROM scope_derivations WHERE workspace_id=work.workspace_id AND id=(event->>'derivation_id')::uuid;
 SELECT * INTO r FROM session_context_scope_revisions WHERE workspace_id=work.workspace_id AND id=selected_frame;
 IF output.resource_kind='session_message' THEN
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(seal.outputs) n WHERE n->>'derivationId'=output.id::text AND n->>'id'=output.resource_id::text)
   OR (SELECT count(*) FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=output.id)<>1
   OR event->>'source_kind' IS DISTINCT FROM 'session_context_revision' OR event->>'source_id' IS DISTINCT FROM selected_frame::text
   OR event->>'source_version' IS DISTINCT FROM '1' OR output.resource_version IS DISTINCT FROM '1'
   OR output.user_id IS DISTINCT FROM r.user_id OR output.assistant_id IS DISTINCT FROM r.assistant_id
   OR sensitivity_rank(output.sensitivity)<sensitivity_rank(r.sensitivity)
   OR NOT output.compartments @> r.compartments OR NOT output.project_ids @> r.project_ids THEN
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 ELSIF output.resource_kind IS DISTINCT FROM 'session_context_revision' OR output.resource_id IS DISTINCT FROM selected_frame THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 UPDATE native_turn_publication_events SET fired=true
 WHERE transaction_id=txid_current() AND frame_id=selected_frame AND native_turn_publication_events.event=native_turn_validate_event.event AND NOT fired;
 IF NOT FOUND THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 RETURN true;
END $$;

CREATE FUNCTION native_turn_complete_publication() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE work native_turn_publication_work;fresh jsonb;item jsonb;message session_messages;d scope_derivations;expected_scope jsonb;actual_scope jsonb;actual_payload jsonb;events jsonb;actual_events jsonb;frame_content jsonb;frame_scope jsonb;
BEGIN
 SELECT * INTO work FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=NEW.frame_id;
 IF work.frame_id IS NULL OR NEW.transaction_id<>txid_current() OR native_turn_helpers_current() IS NOT TRUE
  OR native_turn_context() IS DISTINCT FROM work.context OR native_turn_frame_pair(work.workspace_id,work.frame_id) IS NOT TRUE
  OR NOT EXISTS(SELECT 1 FROM native_turn_publication_debt WHERE transaction_id=txid_current() AND frame_id=work.frame_id)
  OR EXISTS(SELECT 1 FROM native_turn_publication_events WHERE transaction_id=txid_current() AND frame_id=work.frame_id AND NOT fired)
  OR jsonb_typeof(NEW.outputs) IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.outputs) NOT BETWEEN 1 AND 512
 THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 expected_scope:=work.prepared->'scope';
 SELECT c.content,jsonb_build_object('workspaceId',r.workspace_id,'userId',r.user_id,'assistantId',r.assistant_id,
  'sensitivity',r.sensitivity,'compartments',r.compartments,'projectIds',r.project_ids)
 INTO frame_content,frame_scope FROM session_context_scope_revisions r JOIN session_context_revision_contents c
 ON c.workspace_id=r.workspace_id AND c.revision_id=r.id WHERE r.workspace_id=work.workspace_id AND r.id=work.frame_id;
 IF frame_content->'originalSources' IS DISTINCT FROM work.original_sources
  OR frame_content->'declaredSources' IS DISTINCT FROM work.prepared->'retained' OR frame_scope IS DISTINCT FROM expected_scope
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(NEW.outputs) LOOP
  SELECT * INTO message FROM session_messages WHERE workspace_id=work.workspace_id AND session_id=work.session_id AND id=(item->>'id')::uuid;
  SELECT * INTO d FROM scope_derivations WHERE workspace_id=work.workspace_id AND id=(item->>'derivationId')::uuid;
  actual_scope:=jsonb_build_object('workspaceId',message.workspace_id,'userId',message.user_id,'assistantId',message.assistant_id,
   'sensitivity',message.sensitivity,'compartments',message.compartments,'projectIds',message.project_ids);
  actual_payload:=jsonb_build_object('role',message.role,'content',message.content,'channelMessageId',message.channel_message_id,
   'senderUserId',message.sender_user_id,'senderAssistantId',message.sender_assistant_id,'attachments',message.attachments);
  IF message.id IS NULL OR message.scope_held OR scope_review_state_held('session_message',message.id) OR message.scope_version<>1 OR message.sequence_num IS DISTINCT FROM (item->>'sequence')::integer
   OR actual_scope IS DISTINCT FROM expected_scope OR item->>'payloadDigest' IS DISTINCT FROM encode(sha256(convert_to(actual_payload::text,'UTF8')),'hex')
   OR d.id IS NULL OR d.resource_kind IS DISTINCT FROM 'session_message' OR d.resource_id IS DISTINCT FROM message.id OR d.resource_version IS DISTINCT FROM '1'
   OR (d.user_id,d.assistant_id,d.sensitivity,d.compartments,d.project_ids) IS DISTINCT FROM
      (message.user_id,message.assistant_id,message.sensitivity,message.compartments,message.project_ids)
   OR (SELECT count(*) FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id)<>1
   OR NOT EXISTS(SELECT 1 FROM scope_derivation_sources WHERE workspace_id=work.workspace_id AND derivation_id=d.id
    AND source_kind='session_context_revision' AND source_id=work.frame_id AND source_version='1') THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 END LOOP;
 SELECT jsonb_agg(event ORDER BY event::text) INTO events FROM native_turn_publication_events WHERE transaction_id=txid_current() AND frame_id=work.frame_id;
 SELECT jsonb_agg(to_jsonb(e) ORDER BY to_jsonb(e)::text) INTO actual_events FROM scope_derivation_sources e JOIN scope_derivations actual_derivation ON actual_derivation.workspace_id=e.workspace_id AND actual_derivation.id=e.derivation_id
 WHERE actual_derivation.workspace_id=work.workspace_id AND (actual_derivation.resource_kind='session_context_revision' AND actual_derivation.resource_id=work.frame_id
  OR actual_derivation.id IN(SELECT (n->>'derivationId')::uuid FROM jsonb_array_elements(NEW.outputs) n));
 IF events IS NULL OR events IS DISTINCT FROM actual_events THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 -- This command sees all prior writes. Preparation's proof is never consumed here.
 SELECT native_turn_prepare_publication(work.workspace_id,work.session_id,'native:turn-frame',work.original_sources,expected_scope) INTO fresh;
 IF fresh IS NULL OR (fresh-'proof') IS DISTINCT FROM work.prepared
  OR native_turn_context() IS DISTINCT FROM work.context OR native_turn_helpers_current() IS NOT TRUE
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF fresh#>>'{proof,validUntil}' IS NULL OR clock_timestamp()>=(fresh#>>'{proof,validUntil}')::timestamptz THEN
  RAISE EXCEPTION 'native_turn_policy_expired' USING ERRCODE='42501';END IF;
 UPDATE native_turn_publication_work SET completion_ready=true WHERE transaction_id=txid_current() AND frame_id=work.frame_id;
 DELETE FROM native_turn_publication_debt WHERE transaction_id=txid_current() AND frame_id=work.frame_id;
 DELETE FROM native_turn_publication_events WHERE transaction_id=txid_current() AND frame_id=work.frame_id;
 DELETE FROM native_turn_publication_seals WHERE transaction_id=txid_current() AND frame_id=work.frame_id;
 DELETE FROM native_turn_publication_work WHERE transaction_id=txid_current() AND frame_id=work.frame_id;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER application_field_derivation_dependencies AFTER INSERT ON native_turn_publication_seals
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION native_turn_complete_publication();

CREATE FUNCTION public.publish_native_turn_message_batch(w uuid, s uuid, payloads jsonb, producer text, sources jsonb, target jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;parent jsonb;payload jsonb;node jsonb;
 prepared jsonb;fresh jsonb;retained jsonb;source_scope jsonb;stored session_messages;derivation uuid;
 results jsonb:='[]';outputs jsonb:='[]';frame_id uuid:=gen_random_uuid();frame_payload jsonb;frame_derivation uuid;wrote_payload boolean:=false;floor_tier text;teams text[];projects uuid[];
BEGIN
 IF jsonb_typeof(payloads) IS DISTINCT FROM 'array' OR jsonb_array_length(payloads) NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 parent:=lock_native_session_context_publication(w,s);
 FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP
 IF jsonb_typeof(payload) IS DISTINCT FROM 'object' OR NOT payload ?& ARRAY['role','content','channelMessageId','senderUserId','senderAssistantId','attachments']
  OR payload-ARRAY['role','content','channelMessageId','senderUserId','senderAssistantId','attachments']<>'{}'
  OR payload->>'role' NOT IN('user','assistant') OR jsonb_typeof(payload->'role') IS DISTINCT FROM 'string'
  OR jsonb_typeof(payload->'attachments') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'attachments')>100
  OR jsonb_typeof(payload->'channelMessageId') NOT IN('null','string')
  OR jsonb_typeof(payload->'senderUserId') NOT IN('null','string') OR jsonb_typeof(payload->'senderAssistantId') NOT IN('null','string')
  OR jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 4096
  OR length(btrim(producer)) NOT BETWEEN 1 AND 256
  OR entity_derivation_envelope_valid(target) IS NOT TRUE OR target->>'workspaceId' IS DISTINCT FROM w::text
  OR target->>'assistantId' IS NOT NULL OR target->>'userId' IS NOT NULL AND target->>'userId' IS DISTINCT FROM actor::text
  OR parent->>'userId' IS NOT NULL AND parent->>'userId' IS DISTINCT FROM target->>'userId'
  OR payload->>'senderUserId' IS NOT NULL AND payload->>'senderUserId' IS DISTINCT FROM actor::text
  OR payload->>'senderAssistantId' IS NOT NULL AND (payload->>'role'<>'assistant'
   OR payload->>'senderAssistantId' IS DISTINCT FROM nullif(current_setting('app.v2_assistant_id',true),'')) THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 END LOOP;
 IF native_turn_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;
 prepared:=native_turn_prepare_publication(w,s,producer,sources,target);
 IF prepared IS NULL THEN RETURN NULL;END IF;
 retained:=prepared->'retained';source_scope:=prepared->'scope';floor_tier:=source_scope->>'sensitivity';
 teams:=ARRAY(SELECT jsonb_array_elements_text(source_scope->'compartments'));
 projects:=ARRAY(SELECT jsonb_array_elements_text(source_scope->'projectIds')::uuid);
 FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP
 FOR node IN SELECT value FROM jsonb_array_elements(payload->'attachments') LOOP
  IF jsonb_typeof(node) IS DISTINCT FROM 'object' OR node->>'workspaceId' IS DISTINCT FROM w::text
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(retained) input WHERE input->>'resourceKind'='workspace_file' AND input->>'resourceId'=node->>'fileId') THEN
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 END LOOP;
 END LOOP;
 INSERT INTO native_turn_publication_work(transaction_id,workspace_id,frame_id,session_id,context,original_sources,prepared)
 VALUES(txid_current(),w,frame_id,s,native_turn_context(),sources,prepared-'proof');
 frame_payload:=jsonb_build_object('kind','native_turn_frame_v1','originalSources',sources,'declaredSources',retained);
 INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)
 VALUES(frame_id,w,s,'turn_frame',frame_id,(source_scope->>'userId')::uuid,NULL,floor_tier,teams,projects,encode(sha256(convert_to(frame_payload::text,'UTF8')),'hex'));
 INSERT INTO native_turn_frames(workspace_id,id,session_id,format,manifest_digest)
 VALUES(w,frame_id,s,1,encode(sha256(convert_to(frame_payload::text,'UTF8')),'hex'));
 INSERT INTO session_context_revision_contents(workspace_id,revision_id,content) VALUES(w,frame_id,frame_payload);
 INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;
 INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
 SELECT w,'session_context_revision',frame_id,'1',producer,(source_scope->>'userId')::uuid,NULL,floor_tier,teams,projects,revision FROM workspace_access_policies WHERE workspace_id=w RETURNING id INTO frame_derivation;
 INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
 SELECT w,frame_derivation,value->>'resourceKind',(value->>'resourceId')::uuid,value->>'version' FROM jsonb_array_elements(retained) ORDER BY value->>'resourceKind',value->>'resourceId';
 IF native_turn_frame_pair(w,frame_id) IS NOT TRUE THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 -- Once message writes begin, every error aborts the complete publication.
 wrote_payload:=true;
 -- One logical SQL batch writes all rows with complete immutable ancestry.
 FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP
 INSERT INTO session_messages(session_id,role,content,sequence_num,channel_message_id,sender_user_id,sender_assistant_id,attachments,
  workspace_id,user_id,assistant_id,sensitivity,compartments,project_ids,scope_version,scope_held)
  SELECT s,payload->>'role',payload->'content',coalesce(max(sequence_num),0)+1,payload->>'channelMessageId',
   (payload->>'senderUserId')::uuid,(payload->>'senderAssistantId')::uuid,payload->'attachments',w,(target->>'userId')::uuid,NULL,floor_tier,teams,projects,1,false
  FROM session_messages WHERE session_id=s RETURNING * INTO stored;
 IF jsonb_array_length(retained)>0 THEN
  INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;
  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
   SELECT w,'session_message',stored.id,'1',producer,(target->>'userId')::uuid,NULL,floor_tier,teams,projects,revision FROM workspace_access_policies WHERE workspace_id=w RETURNING id INTO derivation;
  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
   VALUES(w,derivation,'session_context_revision',frame_id,'1');
 END IF;
 outputs:=outputs||jsonb_build_array(jsonb_build_object('id',stored.id,'derivationId',derivation,'sequence',stored.sequence_num,
  'payloadDigest',encode(sha256(convert_to(payload::text,'UTF8')),'hex')));
 results:=results||jsonb_build_array(jsonb_build_object('message',jsonb_build_object('id',stored.id,'sessionId',s,'role',stored.role,'content',stored.content,
  'sequenceNum',stored.sequence_num,'createdAt',stored.created_at,'replyToText',NULL,'topicLabel',NULL,'topicConfidence',NULL,
  'channelMessageId',stored.channel_message_id,'senderUserId',stored.sender_user_id,'senderAssistantId',stored.sender_assistant_id,'attachments',stored.attachments),
  'source',source_scope||jsonb_build_object('resourceKind','session_message','resourceId',stored.id,'version','1')));
 END LOOP;
 -- One closing statement orders completion before its mandatory debt check.
 WITH seal AS(INSERT INTO native_turn_publication_seals(transaction_id,frame_id,outputs)
  VALUES(txid_current(),frame_id,outputs) RETURNING native_turn_publication_seals.transaction_id,native_turn_publication_seals.frame_id)
 INSERT INTO native_turn_publication_debt SELECT seal.transaction_id,seal.frame_id FROM seal;
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 RETURN results;
EXCEPTION WHEN SQLSTATE 'PNT02' THEN
 IF wrote_payload THEN RAISE;END IF;
 RETURN NULL;
END $function$;

