-- Authenticate executable metadata; no source admission or principal grants live here.
DO $private$ DECLARE f regprocedure;BEGIN
 FOR f IN SELECT oid::regprocedure FROM pg_proc WHERE pronamespace='public'::regnamespace
 AND(proname IN('native_turn_guard_completion_debt','native_turn_frame_payload_shape','native_turn_frame_pair','native_turn_frame_immutable','native_turn_validate_frame_pair','native_turn_prepare_publication','native_turn_event_frame','native_turn_capture_event','native_turn_validate_event','native_turn_complete_publication','native_turn_publication_contract') OR proname='publish_native_turn_message_batch') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,app_user',f);
  IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=f AND(p.proowner<>(SELECT relowner FROM pg_class WHERE oid='memories'::regclass)
   OR EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
    WHERE a.grantee<>p.proowner OR a.grantor<>p.proowner OR a.is_grantable OR a.privilege_type<>'EXECUTE')))
  THEN RAISE EXCEPTION 'native_turn_publication_private_function_acl: %',f;END IF;
 END LOOP;
END $private$;
DO $table_contract$
DECLARE expression text;expected jsonb;
BEGIN
 expression:=$query$SELECT jsonb_build_object(
 'tables',(SELECT jsonb_agg(jsonb_build_object('oid',c.oid,'owner',c.relowner,'kind',c.relkind,'persistence',c.relpersistence,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'acl',c.relacl) ORDER BY c.oid)
 FROM pg_class c WHERE c.oid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'columns',(SELECT jsonb_agg(jsonb_build_array(attrelid,attnum,attname,atttypid,atttypmod,attnotnull,attidentity,attgenerated,attisdropped,attacl) ORDER BY attrelid,attnum)
 FROM pg_attribute WHERE attnum>0 AND attrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE tgrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'constraints',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) FROM pg_constraint c WHERE conrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'rules',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_rewrite r WHERE ev_class=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'defaults',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.oid) FROM pg_attrdef d WHERE adrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p WHERE polrelid=ANY(ARRAY['native_turn_frames'::regclass,'native_turn_publication_work'::regclass,'native_turn_publication_events'::regclass,'native_turn_publication_seals'::regclass,'native_turn_publication_impossible'::regclass,'native_turn_publication_debt'::regclass])))$query$;
 EXECUTE expression INTO expected;
 EXECUTE 'CREATE FUNCTION native_turn_publication_contract() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS '||quote_literal('SELECT ('||expression||') IS NOT DISTINCT FROM '||quote_literal(expected::text)||'::jsonb');
 REVOKE ALL ON FUNCTION native_turn_publication_contract() FROM PUBLIC,app_user;
 IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid='native_turn_publication_contract()'::regprocedure
  AND(p.proowner<>(SELECT relowner FROM pg_class WHERE oid='memories'::regclass) OR EXISTS(
   SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
   WHERE a.grantee<>p.proowner OR a.grantor<>p.proowner OR a.is_grantable OR a.privilege_type<>'EXECUTE')))
 THEN RAISE EXCEPTION 'native_turn_publication_private_function_acl';END IF;
END $table_contract$;
-- Seal the exact old reader roster plus the authored publication closure.
INSERT INTO native_turn_contract_helpers(signature,fingerprint)
 SELECT p.oid::regprocedure::text,encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') FROM pg_proc p
 WHERE p.pronamespace='public'::regnamespace AND(p.proname IN('native_turn_guard_completion_debt','native_turn_frame_payload_shape','native_turn_frame_pair','native_turn_frame_immutable','native_turn_validate_frame_pair','native_turn_prepare_publication','native_turn_event_frame','native_turn_capture_event','native_turn_validate_event','native_turn_complete_publication','native_turn_publication_contract') OR p.proname IN(
 'publish_native_turn_message_batch','publish_native_session_message_batch','lock_native_session_context_publication',
 'session_context_payload_shape','validate_session_context_revision_pair','validate_scope_resource_reference',
 'validate_application_field_dependencies','enqueue_native_field_dependency_work','session_context_revision_allowed'))
 ON CONFLICT DO NOTHING;
DO $roster$ DECLARE body text;roster text;old_roster text;BEGIN
 SELECT prosrc INTO body FROM pg_proc WHERE oid='native_turn_helpers_current()'::regprocedure;
 SELECT string_agg(quote_literal(signature),',' ORDER BY signature) INTO roster FROM native_turn_contract_helpers;
 old_roster:=substring(body FROM 'array_agg\(h.signature ORDER BY h.signature\)=ARRAY\[(.+)\]::text\[\] AND bool_and');
 IF old_roster IS NULL THEN RAISE EXCEPTION 'Native turn predecessor roster missing';END IF;
 body:=replace(body,'ARRAY['||old_roster||']::text[]','ARRAY['||roster||']::text[]');
 body:=replace(body,'SELECT EXISTS(SELECT 1 FROM pg_class','SELECT native_turn_publication_contract() AND EXISTS(SELECT 1 FROM pg_class');
 EXECUTE replace(pg_get_functiondef('native_turn_helpers_current()'::regprocedure),(SELECT prosrc FROM pg_proc WHERE oid='native_turn_helpers_current()'::regprocedure),body);
END $roster$;
-- The small event contract pins the executable completion fence as well as its tables.
-- The full guard stores fingerprints outside its own body, so this has no hash cycle.
DO $completion_fence$ DECLARE body text;f regprocedure;pin text;BEGIN
 SELECT prosrc INTO body FROM pg_proc WHERE oid='native_turn_publication_contract()'::regprocedure;
 SELECT string_agg(format('(%L::regprocedure,%L::text)',p.oid::regprocedure::text,encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')),',') INTO pin
 FROM pg_proc p WHERE p.oid=ANY(ARRAY['native_turn_complete_publication()'::regprocedure,'native_turn_helpers_current()'::regprocedure]);
 body:='SELECT ('||body||') AND (SELECT count(*)=2 AND bool_and(encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex'')=expected.fingerprint) FROM (VALUES '||pin||') expected(id,fingerprint) JOIN pg_proc p ON p.oid=expected.id)';
 EXECUTE replace(pg_get_functiondef('native_turn_publication_contract()'::regprocedure),(SELECT prosrc FROM pg_proc WHERE oid='native_turn_publication_contract()'::regprocedure),body);
 SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') INTO pin FROM pg_proc p WHERE p.oid='native_turn_publication_contract()'::regprocedure;
 FOREACH f IN ARRAY ARRAY['native_turn_capture_event(jsonb)'::regprocedure,'native_turn_validate_event(jsonb)'::regprocedure,'native_turn_guard_completion_debt()'::regprocedure] LOOP
  SELECT prosrc INTO body FROM pg_proc WHERE oid=f;
  IF position('__PUBLICATION_CONTRACT_PIN__' IN body)=0 THEN RAISE EXCEPTION 'Native publication contract anchor missing';END IF;
  EXECUTE replace(pg_get_functiondef(f),body,replace(body,'__PUBLICATION_CONTRACT_PIN__',pin));
 END LOOP;
 SELECT prosrc INTO body FROM pg_proc WHERE oid='enqueue_native_field_dependency_work()'::regprocedure;
 SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') INTO pin FROM pg_proc p WHERE p.oid='native_turn_capture_event(jsonb)'::regprocedure;
 EXECUTE replace(pg_get_functiondef('enqueue_native_field_dependency_work()'::regprocedure),body,replace(body,'__CAPTURE_EVENT_PIN__',pin));
 SELECT prosrc INTO body FROM pg_proc WHERE oid='validate_application_field_dependencies()'::regprocedure;
 SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') INTO pin FROM pg_proc p WHERE p.oid='native_turn_validate_event(jsonb)'::regprocedure;
 EXECUTE replace(pg_get_functiondef('validate_application_field_dependencies()'::regprocedure),body,replace(body,'__VALIDATE_EVENT_PIN__',pin));
END $completion_fence$;
-- Each downstream pin is rewritten only from an authenticated exact predecessor.
-- Repeat to propagate changes through flat row guards and fingerprint guards.
DO $repin$
DECLARE previous record;caller record;body text;round integer;changed boolean;new_fp text;new_hash text;
BEGIN
 FOR round IN 1..64 LOOP
  changed:=false;
  FOR previous IN SELECT original.*,p.prosrc current_body,
   encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') current_fingerprint,
   encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') current_hash
   FROM native_frame_originals original JOIN pg_proc p ON p.oid=original.oid
   WHERE original.body IS DISTINCT FROM p.prosrc OR original.fingerprint IS DISTINCT FROM encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')
  LOOP
   FOR caller IN SELECT p.oid,p.prosrc FROM pg_proc p
    WHERE p.pronamespace='public'::regnamespace AND p.oid<>previous.oid AND
     (position(previous.quoted_body IN p.prosrc)>0 OR position(previous.fingerprint IN p.prosrc)>0 OR position(previous.body_hash IN p.prosrc)>0)
   LOOP
    IF NOT EXISTS(SELECT 1 FROM native_frame_originals WHERE oid=caller.oid) THEN
     RAISE EXCEPTION 'Native frame unauthenticated pin consumer: %',caller.oid::regprocedure;
    END IF;
    body:=replace(caller.prosrc,previous.quoted_body,quote_literal(previous.current_body));
    body:=replace(body,previous.fingerprint,previous.current_fingerprint);
    body:=replace(body,previous.body_hash,previous.current_hash);
    IF body IS DISTINCT FROM caller.prosrc THEN
     EXECUTE replace(pg_get_functiondef(caller.oid),caller.prosrc,body);changed:=true;
    END IF;
   END LOOP;
   UPDATE native_frame_originals SET body=previous.current_body,quoted_body=quote_literal(previous.current_body),
    fingerprint=previous.current_fingerprint,body_hash=previous.current_hash WHERE oid=previous.oid;
  END LOOP;
  IF NOT changed THEN EXIT;END IF;
  IF round=64 THEN RAISE EXCEPTION 'Native frame pin dependency cycle';END IF;
 END LOOP;
END $repin$;
DO $metadata$ BEGIN
 IF EXISTS(SELECT 1 FROM native_frame_originals original JOIN pg_proc p ON p.oid=original.oid
  WHERE original.metadata IS DISTINCT FROM to_jsonb(p)-'prosrc') THEN RAISE EXCEPTION 'Native frame changed predecessor metadata';END IF;
END $metadata$;
UPDATE native_turn_contract_helpers h SET fingerprint=encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')
 FROM pg_proc p WHERE p.oid=to_regprocedure(h.signature);
DO $$ BEGIN
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'Native turn frame contract failed';END IF;
 IF application_native_worklist_helpers_current() IS NOT TRUE OR application_native_dependency_batch_helpers_current() IS NOT TRUE
  OR application_memory_statement_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'Native frame predecessor guard refresh failed';END IF;
END $$;
COMMIT;
